// The EDAX/TSL inverse-pole-figure colour key of orix 0.15.0 (itself adapted from MTEX), for all eleven Laue classes.
// Sectors: OrixIPFSectors.swift, generated by tools/pins/orix/ipf-pins.py. Pinned in OrixIPFKeyTests (orix-ipf-pins.json).
import Foundation
import simd
import DiffractoCore

extension CrystalOrientationSymmetry {
    /// orix `DirectionColorKeyTSL(symmetry).direction2color(direction)` for this Laue class in the kit's standard
    /// setting (the setting maps to orix's through `OrixIPFSector.frame`), as Double RGB.
    internal func orixIPFColor(_ direction: SIMD3<Double>) -> SIMD3<Double> {
        let sector = OrixIPFSector.sector(for: laueClass)
        // orix's D3d has its twofolds on x: the kit's -3m1 setting is orix's frame itself, the -31m setting is rotated by -30 degrees.
        let frame = threeBarMSetting == .threeBarMOne ? matrix_identity_double3x3 : sector.frame
        let v0 = frame.transpose * simd_normalize(direction)
        let h = foldIntoSector(v0, sector: sector)
        let (azimuth, polar) = Self.polarCoordinates(sector: sector, v: h)
        return Self.rgb(azimuth: azimuth, polar: 0.5 + polar / 2)
    }

    /// orix `Vector3d.in_fundamental_sector` (from MTEX `project2FundamentalRegion`), in orix coordinates.
    private func foldIntoSector(_ v: SIMD3<Double>, sector: OrixIPFSector) -> SIMD3<Double> {
        var v = v
        var group = sector.group
        if laueClass == .threeBar {
            // orix: z < 0 vectors are rotated by element 3 (the inversion), then only the first three elements serve.
            if v.z < 0 { v = -v }
            group = Array(group.prefix(3))
        }
        let centers = group.map { $0 * sector.center }
        var best = 0
        var bestValue = -Double.infinity
        for (i, c) in centers.enumerated() {
            let value = Self.round(simd_dot(v, c), decimals: 12)
            if value > bestValue { bestValue = value; best = i }
        }
        let folded = group[best].transpose * v
        let inside = sector.normals.allSatisfy { simd_dot($0, v) > -1e-9 }
        return inside ? v : folded
    }

    // MARK: polar coordinates (orix plot/direction_color_keys/_util.py)

    private static func polarCoordinates(sector: OrixIPFSector, v h: SIMD3<Double>) -> (Double, Double) {
        let center = unit(sector.center)
        let nVertices = sector.vertices.count
        let v = unit(h)
        let rx = nVertices == 0 ? SIMD3(1, 0, 0) - center : SIMD3(0, 0, 1) - center
        var azimuth = calculateAzimuth(center: center, rx: rx, v: v)
        if nVertices != 0 { azimuth = correctAzimuth(azimuth, sector: sector, rx: rx) }

        var polar: Double
        if sector.normals.allSatisfy({ simd_dot($0, center) == 0 }) {
            polar = angle(center, v) / .pi
        } else {
            let vCenterNormal = unit(simd_cross(v, center))
            polar = .infinity
            for normal in sector.normals {
                let boundary = unit(simd_cross(vCenterNormal, normal))
                var d = angle(-v, boundary) / angle(-center, boundary)
                if d.isNaN { d = 1 }
                polar = min(polar, d)
            }
        }
        return (azimuth, polar)
    }

    private static func calculateAzimuth(center: SIMD3<Double>, rx rx0: SIMD3<Double>, v: SIMD3<Double>) -> Double {
        let rx = unit(rx0 - simd_dot(rx0, center) * center)
        let ry = unit(simd_cross(center, rx))
        let d = unit(v - center)
        let a = atan2(simd_dot(ry, d), simd_dot(rx, d))
        if a.isNaN { return 0 }
        let m = a.truncatingRemainder(dividingBy: 2 * .pi)
        return m < 0 ? m + 2 * .pi : m
    }

    private static func correctAzimuth(_ azimuth: Double, sector: OrixIPFSector, rx: SIMD3<Double>) -> Double {
        let center = unit(sector.center)
        let m = 1000
        let azimuth2 = (0..<m).map { 2 * Double.pi * Double($0) / Double(m - 1) }
        let base = unit(simd_cross(rx, center))
        var polar = [Double](repeating: .infinity, count: m - 1)
        for k in 0..<(m - 1) {
            let a = azimuth2[k]
            let n = base * cos(a) + simd_cross(center, base) * sin(a) + center * (simd_dot(center, base) * (1 - cos(a)))
            for normal in sector.normals {
                polar[k] = min(polar[k], angle(simd_cross(normal, n), center))
            }
        }
        if sector.vertices.count == 3 {
            let vertexAngles = sector.vertices.map { calculateAzimuth(center: center, rx: rx, v: unit($0)) }.sorted()
            var cuts = vertexAngles.map { Int(round(Double(m) * $0 / (2 * .pi), decimals: 0)) }
            if cuts[0] < 10 { cuts.removeFirst() }
            func normalise(_ range: Range<Int>) {
                var s = 0.0
                for i in range { s += polar[i] }
                for i in range { polar[i] /= s / 3 }
            }
            normalise(0..<cuts[0])
            normalise(cuts[0]..<cuts[1])
            normalise(cuts[1]..<polar.count)
        }
        let total = polar.reduce(0, +)
        var cumulative = [0.0]
        var running = 0.0
        for p in polar { running += p / total; cumulative.append(running) }
        let table = cumulative.map { 2 * Double.pi * $0 }
        // numpy.interp on the uniform grid azimuth2.
        if azimuth <= azimuth2[0] { return table[0] }
        if azimuth >= azimuth2[m - 1] { return table[m - 1] }
        var lo = 0, hi = m - 1
        while hi - lo > 1 {
            let mid = (lo + hi) / 2
            if azimuth2[mid] <= azimuth { lo = mid } else { hi = mid }
        }
        let t = (azimuth - azimuth2[lo]) / (azimuth2[hi] - azimuth2[lo])
        return table[lo] + t * (table[hi] - table[lo])
    }

    // MARK: colour

    private static func rgb(azimuth: Double, polar lightness: Double) -> SIMD3<Double> {
        var hue = (azimuth / (2 * .pi)).truncatingRemainder(dividingBy: 1)
        if hue < 0 { hue += 1 }
        let l2 = 2 * lightness
        let s2 = l2 <= 1 ? l2 : 2 - l2
        var saturation = (2 * s2) / (l2 + s2)
        if saturation.isNaN { saturation = 0 }
        let value = (l2 + s2) / 2
        // matplotlib.colors.hsv_to_rgb
        let h6 = hue * 6
        let i = Int(h6)
        let f = h6 - Double(i)
        let p = value * (1 - saturation)
        let q = value * (1 - saturation * f)
        let t = value * (1 - saturation * (1 - f))
        switch i % 6 {
        case 0: return [value, t, p]
        case 1: return [q, value, p]
        case 2: return [p, value, t]
        case 3: return [p, q, value]
        case 4: return [t, p, value]
        default: return [value, p, q]
        }
    }

    // MARK: numpy-matching helpers

    private static func unit(_ x: SIMD3<Double>) -> SIMD3<Double> { x / simd_length(x) }
    /// numpy.round(x, decimals) (half to even on the scaled value).
    private static func round(_ x: Double, decimals: Int) -> Double {
        let s = pow(10.0, Double(decimals))
        return (x * s).rounded(.toNearestOrEven) / s
    }
    /// orix `Vector3d.angle_with`: arccos of the cosine rounded to ten decimals.
    private static func angle(_ a: SIMD3<Double>, _ b: SIMD3<Double>) -> Double {
        acos(round(simd_dot(a, b) / simd_length(a) / simd_length(b), decimals: 10))
    }
}
